export const EXTRA_THEORIES: TheoryEntry[] = COMPACT_THEORIES.map(
  ([id, name, theoryTitle, yearNum, yearDisplay, field, summary, coreConcepts, application, citationApa7]) => ({
    id,
    name,
    initial: name.charAt(0).toUpperCase(),
    theoryTitle,
    yearNum,
    yearDisplay,
    field,
    summary,
    coreConcepts,
    propositions: [
      summary,
      `Konsep sentral dalam pemikiran ${name} mencakup: ${coreConcepts.join(', ')}.`,
      `Aplikasi utama teori ini berfokus pada: ${application}`
    ],
    application,
    citationApa7
  })
);
